BEGIN;
CREATE TEMP TABLE img_expected(id integer PRIMARY KEY, tc_id integer NOT NULL, content text NOT NULL) ON COMMIT DROP;
INSERT INTO img_expected VALUES
(344660,344900,$q${"titleContent": "右图所示,若使主机 A 和主机 B 能够互相访问,则主机 B 正确的网络参数配置是____。<br/><img src=\"/qimg/q344660.jpg\"/>", "analyze": "主机 B 应与主机 A 同网段：192.168.2.20/255.255.255.0，故选 B。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "IP地址:10.10.1.20子网掩码;255.0.0.0", "itemUuid": "b859b342bf6c4b51b8775338d703d926", "score": null}, {"prefix": "B", "content": "IP地址:192.168.2.20子网掩码:255.255.255.0", "itemUuid": "f18e3e5454794e5cb512dd0c5742955a", "score": null}, {"prefix": "C", "content": "IP地址:172.16.2.10子网掩码:255.255.0.0", "itemUuid": "d158f1052bf944e8b218ee67b85b5a4e", "score": null}, {"prefix": "D", "content": "IP 地址:192.168.3.100 子网掩码:255.255.255.0", "itemUuid": "f04eac9de60a4ec1b9b9e6339bd724db", "score": null}]}$q$),
(370126,370366,$q${"titleContent": "<br/><br/>部门、员工和项目的关系模式及它们之间的E-R图如下所示，其中，关系模式中带实下画线的属性表示主键；图中部门（部门代码，部门名称，电话）；<br/><br/><br/><br/><br/>员工（员工代码，姓名，部门代码，联系方式，薪资）<br/><br/>项目（项目编号，项目名称，承担任务）<br/><br/><br/><br/>若部门和员工关系进行自然连接运算，其结果集为____元（即多少个属性）关系。由于员工与项目系统之间的类型为____，所以员工和项目之间的联系需要转成一个独立的关系模式，该关系模式的主键是____。<br/><img src=\"/qimg/q370126.jpg\"/>", "analyze": "部门(3)与员工(5)自然连接去公共属性得 7 元关系；员工与项目为多对多，联系模式主键为（项目编号，员工代码），故选 A。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "7, 多对多；（项目编号，员工代码）", "itemUuid": "c84d3eb2e99742be9bef949586a89061", "score": null}, {"prefix": "B", "content": "8, 多对多；（项目编号，员工代码）", "itemUuid": "b7ea3bd2ded24600a74cb1195b02ebd5", "score": null}, {"prefix": "C", "content": "7,一对多；（项目名称，员工代码）", "itemUuid": "012cef93a3bd45ffb07f032540c549b3", "score": null}, {"prefix": "D", "content": "8;一对多；（项目名称，员工代码）", "itemUuid": "3f7e8b738fe6497fbeb9910a9a2ace0a", "score": null}]}$q$);
UPDATE t_text_content t SET content=e.content FROM img_expected e WHERE t.id=e.tc_id;
UPDATE t_question q SET has_image=true FROM img_expected e WHERE q.id=e.id AND NOT q.is_golden;
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM t_question q JOIN img_expected e ON e.id=q.id WHERE q.has_image; IF n<>2 THEN RAISE EXCEPTION 'has_image'; END IF;
 SELECT count(*) INTO n FROM t_text_content t JOIN img_expected e ON e.tc_id=t.id WHERE t.content=e.content AND pg_input_is_valid(t.content,'json'); IF n<>2 THEN RAISE EXCEPTION 'content'; END IF;
 SELECT count(*) INTO n FROM t_question q JOIN t_question_backup_20261118_lane1b b ON b.id=q.id WHERE q.correct IS DISTINCT FROM b.correct OR q.question_type IS DISTINCT FROM b.question_type; IF n<>0 THEN RAISE EXCEPTION 'changed'; END IF;
END $$;
COMMIT;
